js='''const I18N=__I18N__;let lang='en';const reduce=matchMedia('(prefers-reduced-motion: reduce)'),intro=document.querySelector('#intro'),skip=document.querySelector('#skip'),about=document.querySelector('.about-copy');let timer=null,observer=null;function finishIntro(){intro.classList.remove('active');intro.setAttribute('aria-hidden','true');skip.tabIndex=-1;clearTimeout(timer);if(document.activeElement===skip)document.querySelector('#replay').focus()}function playIntro(){if(reduce.matches)return;clearTimeout(timer);intro.classList.remove('active');void intro.offsetWidth;intro.classList.add('active');intro.setAttribute('aria-hidden','false');skip.tabIndex=0;timer=setTimeout(finishIntro,1050)}function prepareReveal(){if(reduce.matches||about.classList.contains('revealed'))return;about.classList.add('reveal-ready');observer=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){about.classList.add('revealed');observer.disconnect()}})},{threshold:.15});observer.observe(about)}playIntro();prepareReveal();skip.onclick=finishIntro;document.querySelector('#replay').onclick=playIntro;document.addEventListener('keydown',e=>{if(e.key==='Escape')finishIntro()});reduce.addEventListener('change',()=>{if(reduce.matches){finishIntro();about.classList.add('revealed');observer?.disconnect()}});document.querySelectorAll('button[data-lang]').forEach(b=>b.onclick=()=>{lang=b.dataset.lang;document.documentElement.lang=lang;document.documentElement.dataset.lang=lang;document.querySelectorAll('[data-i18n]').forEach(e=>e.innerHTML=I18N[lang][e.dataset.i18n]);document.querySelectorAll('button[data-lang]').forEach(x=>x.setAttribute('aria-pressed',x.dataset.lang===lang));document.querySelector('#estimate').textContent=''});document.querySelector('#session-form').onsubmit=e=>{e.preventDefault();const h=Number(document.querySelector('#hours').value),area=document.querySelector('#area');if(!Number.isInteger(h)||h<1||h>12)return;const total=new Intl.NumberFormat(lang,{style:'currency',currency:'EUR'}).format(h*Number(area.value));document.querySelector('#estimate').textContent=I18N[lang].result.replace('{hours}',h).replace('{area}',I18N[lang].areas[area.selectedIndex]).replace('{total}',total)};'''.replace('__I18N__',json.dumps({'en':en,'ru':ru},ensure_ascii=False))
