js += r"""
// React Bits SplitText: word grouping + staggered from/to entrance, ported to WAAPI.
const runningMotion=new Set();
function animateMotion(el,frames,options){
  const a=el.animate(frames,options);runningMotion.add(a);
  a.finished.then(()=>runningMotion.delete(a)).catch(()=>runningMotion.delete(a));
  return a;
}
function revealHeroWords(){
  const heading=document.querySelector('.hero h1');
  if(reduce.matches)return;
  const text=heading.textContent;
  heading.setAttribute('aria-label',text);
  heading.replaceChildren();
  text.split(/(\s+)/).forEach(part=>{
    if(!part.trim()){heading.append(document.createTextNode(part));return}
    const mask=document.createElement('span');mask.className='hero-word-mask';mask.setAttribute('aria-hidden','true');
    const word=document.createElement('span');word.className='hero-word';word.textContent=part;mask.append(word);heading.append(mask);
  });
  heading.querySelectorAll('.hero-word').forEach((word,i)=>animateMotion(word,
    [{transform:'translateY(110%)',opacity:0},{transform:'translateY(0)',opacity:1}],
    {duration:650,delay:i*24,easing:'cubic-bezier(.22,1,.36,1)',fill:'backwards'}));
}
// AnimatedContent: once-only entry, distance/duration/delay adapted per content group.
const extraTargets=[document.querySelector('.work'),...document.querySelectorAll('.tool'),document.querySelector('.session-grid')];
const extraObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{
  if(!entry.isIntersecting)return;
  const el=entry.target;extraObserver.unobserve(el);el.classList.remove('motion-pending');
  if(!reduce.matches)animateMotion(el,[{opacity:0,transform:'translateY(32px)'},{opacity:1,transform:'translateY(0)'}],{duration:700,easing:'cubic-bezier(.22,1,.36,1)'});
}),{threshold:.12});
extraTargets.forEach(el=>{el.dataset.motionExample='react-bits.animated-content';if(!reduce.matches){el.classList.add('motion-pending');extraObserver.observe(el)}});
const originalFinishIntro=finishIntro;
finishIntro=function(){const wasActive=intro.classList.contains('active');originalFinishIntro();if(wasActive)revealHeroWords()};
clearTimeout(timer);if(intro.classList.contains('active'))timer=setTimeout(()=>finishIntro(),1050);
skip.onclick=()=>finishIntro();
document.querySelectorAll('button[data-lang]').forEach(button=>button.addEventListener('click',()=>{if(!intro.classList.contains('active'))revealHeroWords()}));
reduce.addEventListener('change',()=>{if(reduce.matches){runningMotion.forEach(a=>a.cancel());extraObserver.disconnect();extraTargets.forEach(el=>el.classList.remove('motion-pending'))}});
"""
